cat > /tmp/test_config.json << 'EOF'
{
  "os": ["ubuntu-latest", "windows-latest"],
  "language_version": ["1.0", "1.1"],
  "features": []
}
EOF

config=$(cat /tmp/test_config.json)
echo "$config" | jq '
{
  matrix: {
    include: [
      (.os[] as $os |
       .language_version[] as $lang |
       {os: $os, language_version: $lang, features: .features})
    ]
  },
  strategy: {
    ("max-parallel"): 4,
    ("fail-fast"): true
  }
}
'

