# Generate complete output using jq
jq '
  # Build the base matrix by combining all OS and language_version combinations
  (.os as $os_list |
   .language_version as $lang_list |
   (.exclude // []) as $exclude_rules |
   (.include // []) as $include_rules |
   (.features // []) as $features |
   (.max_parallel // 4) as $max_parallel |
   (.fail_fast // true) as $fail_fast |

    # Generate base entries
    [
      ($os_list[] as $os |
       $lang_list[] as $lang |
       # Check if entry should be excluded
       if (
         $exclude_rules | map(
           select(
             (.os == null or .os == $os) and
             (.language_version == null or .language_version == $lang)
           )
         ) | length
       ) == 0
       then
         {os: $os, language_version: $lang, features: $features}
       else
         empty
       end
      )
    ] as $base_entries |

    # Combine base entries with explicit include entries
    {
      matrix: {
        include: ($base_entries + $include_rules),
        exclude: (if ($exclude_rules | length) > 0 then $exclude_rules else empty end)
      },
      strategy: {
        ("max-parallel"): ($max_parallel | tonumber),
        ("fail-fast"): $fail_fast
      }
    }
  )
  ' <<< "$config"

